-- MENU SEED PLACEHOLDER. The grand opening flyer lists only the five categories (Shawarma,
-- Loaded Fries, Gas Meat, Noodles, Masa), not individual items or prices, so nothing is
-- inserted yet. This is a safe no-op: the only row below matches no category.
--
-- When the real menu is known, DO NOT edit this file. Add a new migration with the same
-- statement and fill the rows as (category slug, name, description, price in naira), e.g.
--   ('shawarma', 'Chicken Shawarma', 'Grilled chicken, veg and sauce', 3500),
-- Slugs: shawarma, loaded-fries, gas-meat, noodles, masa. Re-running is safe (skips existing names).
insert into public.menu_items (category_id, name, description, price_kobo)
select c.id, v.name, v.description, v.price_naira * 100
from (values
  ('', '', '', 0)
) as v(slug, name, description, price_naira)
join public.categories c on c.slug = v.slug
where v.name <> ''
  and not exists (select 1 from public.menu_items m where m.category_id = c.id and m.name = v.name);
